module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] current_state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= 2'b00;
        else begin
            case (current_state)
                2'b00: current_state <= 2'b01;
                2'b01: current_state <= 2'b10;
                2'b10: current_state <= 2'b00;
                default: current_state <= 2'b00;
            endcase
        end
    end

    assign state = current_state;
endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg [1:0] state;
    localparam GREEN = 2'd0, YELLOW = 2'd1, RED = 2'd2;

    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= GREEN;
        else begin
            case (state)
                GREEN:  state <= YELLOW;
                YELLOW: state <= RED;
                RED:    state <= GREEN;
                default: state <= GREEN;
            endcase
        end
    end

    assign light = (state == GREEN)  ? 3'b001 :
                   (state == YELLOW) ? 3'b010 :
                   (state == RED)    ? 3'b100 : 3'b001;
endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    localparam IDLE = 2'b00, UP = 2'b01, DOWN = 2'b10;

    reg [1:0] current_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            IDLE: begin
                if (up_request)
                    next_state = UP;
                else if (down_request)
                    next_state = DOWN;
                else
                    next_state = IDLE;
            end
            UP: begin
                if (~up_request)
                    next_state = IDLE;
                else
                    next_state = UP;
            end
            DOWN: begin
                if (~down_request)
                    next_state = IDLE;
                else
                    next_state = DOWN;
            end
            default: next_state = IDLE;
        endcase
    end

    assign state = current_state;
endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);
    localparam IDLE = 2'b00, COIN = 2'b01, DISPENSE = 2'b10;
    reg [1:0] current_state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= IDLE;
        else begin
            case (current_state)
                IDLE:     current_state <= coin_inserted ? COIN : IDLE;
                COIN:     current_state <= item_selected ? DISPENSE : COIN;
                DISPENSE: current_state <= IDLE;
                default:  current_state <= IDLE;
            endcase
        end
    end

    assign state = current_state;
endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);

    integer i;
    reg signed [15:0] result;

    always @(*) begin
        result = 16'sd1;
        for (i = 0; i < 8; i = i + 1) begin
            if (i < in_1)
                result = result * in_0;
        end
    end

    assign out = result;

endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);
    function automatic [7:0] clog2;
        input [15:0] val;
        integer i;
        begin
            clog2 = 0;
            if (val > 0) begin
                for (i = 15; i >= 0; i = i - 1) begin
                    if (val[i] && clog2 == 0) begin
                        clog2 = i[7:0];
                    end
                end
            end
        end
    endfunction

    assign out = (in_0 <= 0) ? 8'sd0 : $signed(clog2(in_0));

endmodule

