module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    wire [7:0] shifted;
    assign shifted = data_in + 8'd3;

    wire is_upper = (data_in >= 8'd65) && (data_in <= 8'd90);
    wire is_lower = (data_in >= 8'd97) && (data_in <= 8'd122);

    wire [7:0] upper_out = (shifted > 8'd90) ? (shifted - 8'd26) : shifted;
    wire [7:0] lower_out = (shifted > 8'd122) ? (shifted - 8'd26) : shifted;

    assign data_out = is_upper ? upper_out :
                      is_lower ? lower_out :
                      data_in;
endmodule

