module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010;

    wire [3:0] left_in, right_in;
    wire [3:0] f_out;
    wire [3:0] new_left, new_right;

    assign left_in = data_in[7:4];
    assign right_in = data_in[3:0];

    assign f_out = right_in ^ KEY;

    assign new_left = right_in;
    assign new_right = left_in ^ f_out;

    assign data_out = {new_left, new_right};

endmodule

