module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  reg [1:0] state, next_state;
  localparam IDLE = 2'd0, A = 2'd1, B = 2'd2, C = 2'd3;

  always @(posedge clk or negedge resetn) begin
    if (!resetn)
      state <= IDLE;
    else
      state <= next_state;
  end

  always @(*) begin
    case (state)
      IDLE: begin
        if (r[0])      next_state = A;
        else if (r[1])  next_state = B;
        else if (r[2])  next_state = C;
        else             next_state = IDLE;
      end
      A: next_state = r[0] ? A : IDLE;
      B: next_state = r[1] ? B : IDLE;
      C: next_state = r[2] ? C : IDLE;
      default: next_state = IDLE;
    endcase
  end

  assign g[0] = (state == A);
  assign g[1] = (state == B);
  assign g[2] = (state == C);

endmodule

