  localparam S0=0, S1=1, S2=2, S3=3, S4=4, S5=5, S6=6, S7=7, S8=8;

  reg [3:0] state, next;

  always @(posedge clk) begin
    if (reset) state <= S0;
    else state <= next;
  end

  always @(*) begin
    case (state)
      S0: next = in ? S1 : S0;
      S1: next = in ? S2 : S0;
      S2: next = in ? S3 : S0;
      S3: next = in ? S4 : S0;
      S4: next = in ? S5 : S0;
      S5: next = in ? S6 : S0;
      S6: next = in ? S7 : S8;
      S7: next = in ? S7 : S0;
      S8: next = in ? S1 : S0;
      default: next = S0;
    endcase
  end

  assign disc = (state == S6) && (!in);
  assign flag = (state == S6) && (!in) ? 0 : 0;
  assign err  = (state == S7);

  // Reconsider: after 6 ones (S6), if next bit is 0 -> disc, if next bit is 1 -> S7 (error pending)
  // After 5 ones (S5), if 0 -> disc (bit stuffing discard), but wait...
  // HDLC: 5 ones + 0 = discard, 6 ones + 0 = flag (01111110), 7+ ones = error

  // Let me redefine states as count of consecutive 1s seen:
  // S0=0 ones, S1=1, S2=2, S3=3, S4=4, S5=5, S6=6, S7=7+
  // disc: in state S5 (seen 5 ones) and in=0 -> discard
  // flag: in state S6 (seen 6 ones) and in=0 -> flag (01111110)
  // err: in state S7 or (state S6 and in=1)

endmodule

