module TopModule (
  input clk,
  input in,
  input reset,
  output done
);
  // Serial byte receiver: detects start bit (0), receives 8 data bits, checks stop bit (1)
  localparam IDLE = 0, START = 1, DATA = 2, STOP = 3, ERROR = 4;

  reg [2:0] state;
  reg [3:0] count;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      count <= 0;
    end else begin
      case (state)
        IDLE: if (~in) state <= DATA; // start bit detected
        DATA: begin
          if (count == 7) begin
            count <= 0;
            state <= in ? STOP : ERROR;
          end else
            count <= count + 1;
        end
        STOP: state <= in ? IDLE : DATA; // if in=0, new start bit
        ERROR: if (in) state <= IDLE;
      endcase
    end
  end

  assign done = (state == STOP);
endmodule

