module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

always @(posedge clk or negedge rst_n) begin
  if (!rst_n)
    out <= 4'd0;
  else if (valid_count) begin
    if (out == 4'd11)
      out <= 4'd0;
    else
      out <= out + 4'd1;
  end
end

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg a_delay;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n)
		a_delay <= 1'b0;
	else
		a_delay <= a;
end

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		rise <= 1'b0;
		down <= 1'b0;
	end else begin
		rise <= a & ~a_delay;
		down <= ~a & a_delay;
	end
end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [31:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 0;
            clk_div <= 0;
        end else if (cnt == (NUM_DIV/2 - 1)) begin
            cnt <= 0;
            clk_div <= ~clk_div;
        end else begin
            cnt <= cnt + 1;
        end
    end

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);

    reg [7:0] ins_reg1;
    reg [7:0] ins_reg2;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            ins_reg1 <= 8'b0;
            ins_reg2 <= 8'b0;
        end else begin
            if (fetch == 2'b01)
                ins_reg1 <= data;
            else if (fetch == 2'b10)
                ins_reg2 <= data;
        end
    end

    assign ins = ins_reg1[7:5];
    assign ad1 = ins_reg1[4:0];
    assign ad2 = ins_reg2;

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  wire feedback;
  assign feedback = out[3] ^ out[2];

  always @(posedge clk or posedge rst) begin
    if (rst)
      out <= 4'b0001;
    else
      out <= {out[2:0], feedback};
  end
endmodule

