module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg [3:0] data_reg;
reg       en_a;
reg       en_b1, en_b2;

// Capture data and enable in clk_a domain
always @(posedge clk_a or negedge arstn) begin
	if (!arstn) begin
		data_reg <= 4'b0;
		en_a <= 1'b0;
	end else begin
		data_reg <= data_in;
		en_a <= data_en;
	end
end

// Synchronize enable to clk_b domain
always @(posedge clk_b or negedge brstn) begin
	if (!brstn) begin
		en_b1 <= 1'b0;
		en_b2 <= 1'b0;
	end else begin
		en_b1 <= en_a;
		en_b2 <= en_b1;
	end
end

// Capture data in clk_b domain when synchronized enable is high
always @(posedge clk_b or negedge brstn) begin
	if (!brstn)
		dataout <= 4'b0;
	else if (en_b2)
		dataout <= data_reg;
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [2:0] state, next_state;

parameter S0 = 3'd0, S1 = 3'd1, S2 = 3'd2, S3 = 3'd3, S4 = 3'd4;

always @(posedge CLK or posedge RST) begin
    if (RST)
        state <= S0;
    else
        state <= next_state;
end

always @(*) begin
    case (state)
        S0: begin
            if (IN) next_state = S1;
            else next_state = S0;
        end
        S1: begin
            if (IN) next_state = S1;
            else next_state = S2;
        end
        S2: begin
            if (IN) next_state = S3;
            else next_state = S0;
        end
        S3: begin
            if (IN) next_state = S4;
            else next_state = S2;
        end
        S4: begin
            if (IN) next_state = S1;
            else next_state = S2;
        end
        default: next_state = S0;
    endcase
end

always @(*) begin
    MATCH = (state == S4);
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    reg [1:0] cnt;
    reg [3:0] data;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 2'd0;
        else
            cnt <= cnt + 2'd1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            data <= 4'd0;
        else if (cnt == 2'd0)
            data <= d;
        else
            data <= {data[2:0], 1'b0};
    end

    assign dout = data[3];
    assign valid_out = 1'b1;

endmodule

